      // daraja: mavzu ichidagi o'rniga qarab (boshi — oson, oxiri — qiyin); ha/yo'q — oson, tartiblash — qiyin
      var pool = qs.map(function (x, i) { return { x: x, L: x.t === "tf" ? 1 : x.t === "o" ? 3 : 1 + Math.min(2, Math.floor(i * 3 / n)) }; });
